import { POLICY, DAYS, localDate, addDays, weekday, defaultProfile, analyze, propose, changes, restoreFuture, validateActivity, planningContext, fromStrava, assessTraining, PERSONAL_RECOVERY_END, isQualityWorkout, deviceWorkout, workoutZwo, workoutSetupText, defaultStrengthSettings, strengthProposal, undoStrengthWeek } from './engine.js';
import { KEY, load, save, initialState, acceptProposal, createStravaWorkspace, validateState } from './storage.js';
import { stravaConnection } from './integrations.js';
import { calendarWindow, dateInZone, evaluateActivity } from './sensors.js';

const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
let state, loadError = '', view = 'week', selectedRecovery = null, pending = null, toastTimer, strengthSelectedWeek=null;
let stravaStatus = { loading: true, connected: false }, stravaActivities = [], stravaBusy = false, stravaVisible = 50;
let localState, stravaWorkspace = null, useStravaCoaching = true, showLocalHistory = false, rejectedStrava = [];
const allowedViews=['week','strength','history','profile','connection','privacy'];
if (allowedViews.includes(location.hash.slice(1))) view = location.hash.slice(1);
try { state = load(); } catch (e) { state = initialState(); loadError = `Saved data could not be loaded: ${e.message} Existing data was not overwritten. Export or delete it in Data & privacy.`; }
state.profile.recoveryWeekEnd ??= PERSONAL_RECOVERY_END;
// Rider requested 12–13 hours. Start at 12; day-by-day slots are visible proposed assumptions.
if(state.profile.personalSetupVersion!==2){
  state.profile.weeklyTargetMinutes=720;
  if(!state.onboarded)Object.assign(state.profile,{goal:'endurance',experience:'consistent',availability:[150,0,90,90,90,60,240],availabilityAssumed:true});
  state.profile.personalSetupVersion=2;
}
if(state.profile.coachSetupVersion!==1){
  Object.assign(state.profile,{goal:'racing',availability:[120,0,100,100,100,60,240],availabilityAssumed:false,coachSetupVersion:1});
}
state.strengthRoom??={plans:[],records:[]};
localState = state;
const today = () => localDate(state.profile.timezone);
const fmtDate = (d, opts = { month: 'short', day: 'numeric' }) => new Intl.DateTimeFormat('en-CA', { ...opts, timeZone: 'UTC' }).format(new Date(d + 'T12:00:00Z'));
const duration = raw => { const m=Math.round(raw); return m >= 60 ? `${Math.floor(m / 60)}h${m % 60 ? ` ${m % 60}m` : ''}` : `${m} min`; };
const sourceLabel = () => state.mode === 'synthetic' ? 'Synthetic example' : state.mode === 'strava' ? 'Actual Strava history' : 'Manually recorded';
const goalLabel = () => ({ consistency: 'Return to consistent riding', fitness: 'General fitness', endurance: 'Build endurance', event: 'Prepare for an event', climbing: 'Ride hills comfortably', racing: 'Build a racing foundation' }[state.profile.goal]);
function notify(message) { $('#toast').textContent = message; clearTimeout(toastTimer); toastTimer = setTimeout(() => $('#toast').textContent = '', 6000); }
function commit(mutator) {
  if (loadError) { notify('Resolve the saved-data problem in Data & privacy before saving.'); return false; }
  const next = structuredClone(state);
  try {
    mutator(next);
    if (next.mode === 'strava') {
      validateState(next,{ephemeral:true});
      if(JSON.stringify(next.profile)!==JSON.stringify(localState.profile)||next.onboarded!==localState.onboarded||JSON.stringify(next.strengthRoom)!==JSON.stringify(localState.strengthRoom)){const localNext={...structuredClone(localState),profile:structuredClone(next.profile),onboarded:next.onboarded,strengthRoom:structuredClone(next.strengthRoom)};save(localNext);localState=localNext;}
      next.revision++;stravaWorkspace=next;
    } else {save(next);localState=next;}
    state = next; render(); return true;
  } catch (e) { notify(`Not saved: ${e.message}`); return false; }
}
function openModal(html) { $('#modal-content').innerHTML = html; if (!$('#modal').open) $('#modal').showModal(); }
const modalHeading = (title, subtitle = '') => `<div class="modal-heading"><div><h2 id="modal-title">${esc(title)}</h2>${subtitle ? `<p class="helper">${esc(subtitle)}</p>` : ''}</div><button class="close" data-action="close" aria-label="Close dialog">×</button></div>`;
function currentPlan() {
  if(state.plan) return state.plan;
  try { return propose(state.profile,state.activities,today(),null,planningContext(state.profile,today())); }
  catch { const paused=propose({...state.profile,goal:'consistency',limitation:'restricted'},state.activities,today(),null,planningContext(state.profile,today()));paused.reasons.unshift('Your saved event date has passed. Update your goal before generating a new plan.');return paused; }
}
function render() {
  document.querySelectorAll('[data-view]').forEach(b => { b.classList.toggle('active', b.dataset.view === view); if (b.dataset.view === view) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current'); });
  $('#breadcrumb').textContent = `TRAINING / ${{week:'MY WEEK',strength:'STRENGTH ROOM',history:'RIDE HISTORY',profile:'GOALS & AVAILABILITY',connection:'CONNECTIONS',privacy:'DATA & PRIVACY'}[view]}`;
  $('#profile-shortcut').textContent = (state.profile.name || 'R').slice(0, 1).toUpperCase();
  $('#data-banner').innerHTML = view==='strength' ? '<span><strong>PERSONAL STRENGTH ROOM</strong> · Uses your gym setup and manual feedback. Cycling sample or Strava records do not establish lifting loads.</span>' : state.mode === 'strava' ? `<span><strong>ACTUAL STRAVA HISTORY</strong> · Local rules use your recorded training. Proposals and evidence remain temporary; no API data is exported or saved to browser storage.</span><button data-action="coaching-local">Manual coaching inputs →</button>` : state.mode === 'synthetic' ? '<span><strong>SYNTHETIC COACHING DATA</strong> · These plan inputs are fictional.</span><button data-action="switch-manual">Use my own rides →</button>' : '<span><strong>MANUAL COACHING DATA</strong> · Recommendations use manually recorded rides.</span><button data-action="coaching-strava">Use connected Strava history →</button>';
  $('#content').innerHTML = (loadError ? `<div class="notice error">${esc(loadError)}</div>` : '') + ({ week: weekView, strength: strengthView, history: historyView, profile: profileView, connection: connectionView, privacy: privacyView }[view])();
  $('#offline').hidden = navigator.onLine;
}
function chart(a) {
  const max = Math.max(1, ...a.weekly.map(w => w.minutes));
  return `<div class="chart" role="img" aria-label="Weekly riding time: ${a.weekly.map(w => `${esc(w.start)} to ${esc(w.end)}: ${w.minutes} minutes`).join('; ')}">${a.weekly.map((w, i) => `<div class="chart-column"><strong>${duration(w.minutes)}</strong><div class="bar h${Math.round(w.minutes / max * 10)}"></div><small>${i === 3 ? 'Latest 7 days' : fmtDate(w.start)}</small></div>`).join('')}</div>`;
}
function weekView() {
  const a = analyze(state.activities, today()), plan = currentPlan(), w = plan.workouts.find(w => w.date === today());
  const accepted = !!state.plan, total = plan.workouts.reduce((s, w) => s + w.minutes, 0), rides = plan.workouts.filter(w => w.minutes).length;
  const future=plan.startDate>today(),recovery=state.profile.recoveryWeekEnd&&today()<=state.profile.recoveryWeekEnd;
  return `<div class="page-heading"><div><div class="eyebrow">A LITTLE DIRECTION. A LOT OF POSSIBILITY.</div><h1>${future ? 'Your next week.' : state.profile.name ? `Your week, ${esc(state.profile.name)}.` : 'Find your rhythm.'}</h1><p>${fmtDate(plan.startDate)} – ${fmtDate(addDays(plan.startDate, 6), { month: 'short', day: 'numeric', year: 'numeric' })} · ${esc(goalLabel())}</p></div><button class="btn secondary" data-action="${state.onboarded ? 'rebuild' : 'setup'}">${state.onboarded ? '↻ Review new proposal' : 'Set up my plan'} <span>↗</span></button></div>
  ${!accepted ? '<div class="notice"><strong>Your weekly proposal is ready to explore.</strong>Review goals, available time, and assumptions before accepting. No workouts are scheduled yet. Availability and goals remain visible assumptions until confirmed.</div>' : ''}
  ${recovery ? `<div class="notice success"><strong>Recovery week through Sunday, ${fmtDate(state.profile.recoveryWeekEnd)}.</strong>The next proposal starts ${fmtDate(plan.startDate,{weekday:'long',month:'short',day:'numeric'})}. No catch-up workouts are added to this recovery week; poor recovery feedback still reduces next week.</div>` : ''}
  ${state.profile.availabilityAssumed?'<div class="notice"><strong>12-hour target · proposed time slots</strong>Monday rest; Tuesday–Thursday 90 min/day; Friday 60 min; Saturday 240 min; Sunday 150 min. These are editable scheduling assumptions. Review Goals & availability before accepting.</div>':''}
  ${state.mode==='strava' ? assessmentCard() : ''}
  ${coachCard(plan)}<section class="notice"><strong>Thursday & Sunday · Strength room</strong>Separate strength prescriptions, exercise instructions, and completion feedback.<br><button class="text-link" data-view="strength">Open Strength room →</button></section>
  ${plan.conflicts.length ? `<div class="notice error">${plan.conflicts.map(esc).join('<br>')}</div>` : ''}
  <div class="dashboard-grid"><section class="today-card"><div class="card-top"><span class="small-label">${w ? 'TODAY’S ' + (accepted ? 'WORKOUT' : 'PROPOSAL') : 'YOUR NEXT STEP'}</span><span class="badge outline">${accepted ? 'Accepted plan' : 'Proposal · not accepted'}</span></div><h2>${esc(w?.title || (recovery ? 'Finish your recovery week' : future ? 'Your next week is ready' : 'A fresh week awaits'))}</h2><p>${esc(w?.purpose || (future ? `Keep your recovery time through ${state.profile.recoveryWeekEnd || 'the weekend'}. Review the proposal starting ${plan.startDate} using your current history and availability.` : 'Your accepted week has ended. Review a fresh proposal.'))}</p><div class="workout-stats"><div><strong>${w ? w.minutes : '—'}</strong> <small>min</small><span>Planned duration</span></div><div><strong>${w?.minutes ? Math.max(...w.steps.map(s=>s.target)) : '—'}</strong> <small>${w?.steps[0]?.unit==='W'?'W':'/ 10'}</small><span>${w?.minutes ? (w.steps[0]?.unit==='W'?'Peak prescribed watts':'Peak prescribed RPE') : 'Time to recover'}</span></div></div><div class="actions">${w ? `<button class="btn" data-workout="${esc(w.id)}">View ${w.minutes ? 'workout' : 'rest day'} <span>↗</span></button>` : '<button class="btn" data-action="rebuild">Review next week →</button>'}<span class="helper">${w ? esc(w.status === 'planned' ? 'Room to adjust. Always.' : `Recorded: ${w.status}`) : ''}</span></div></section>
  <section class="card recovery-card"><div class="small-label">A QUICK CHECK-IN</div><h2>How are you feeling?</h2><p>Your plan should meet you where you are today. A harder day is a reason to ease off.</p><div class="recovery-options"><button class="recovery-choice ${selectedRecovery === 'normal' ? 'selected' : ''}" data-recovery="normal" aria-pressed="${selectedRecovery === 'normal'}"><span>☀</span>Feeling ready</button><button class="recovery-choice ${selectedRecovery === 'poor' ? 'selected' : ''}" data-recovery="poor" aria-pressed="${selectedRecovery === 'poor'}"><span>☁</span>Need it easier</button></div><button class="btn secondary" data-action="recovery-preview">Preview adjustment →</button><p class="helper">Current setting: ${state.profile.recovery === 'poor' ? 'poor recovery · reduced plan' : 'normal recovery'}</p><button class="text-link" data-view="profile">Illness, injury, or concerning symptoms?</button></section></div>
  <div class="section-title"><h2>Your proposed training week</h2><span>${rides} rides · ${duration(total)} planned · ${esc(plan.timezone)}</span></div>
  <div class="calendar">${plan.workouts.map(d => `<button class="day ${d.date === today() ? 'today' : ''}" data-workout="${esc(d.id)}" aria-label="${esc(d.date)}: ${esc(d.title)}, ${d.minutes} minutes, ${esc(d.status)}${d.locked ? ', locked' : ''}"><div class="day-head"><span>${DAYS[weekday(d.date)].slice(0,3).toUpperCase()}${d.date === today() ? ' · TODAY' : ''}</span><strong>${fmtDate(d.date, { day: 'numeric' })}</strong></div><span class="day-symbol" aria-hidden="true">${d.minutes ? '↗' : '◌'}</span><span class="day-title">${esc(d.title)}</span><span class="day-duration">${d.minutes ? duration(d.minutes) + (isQualityWorkout(d)?' · Quality':' · Easy') : 'Rest day'}</span><span class="day-status">${d.locked ? '◆ Locked · ' : ''}${accepted ? esc(d.status) : 'Proposed'}</span></button>`).join('')}</div>
  <div class="lower-grid"><section class="card"><div class="small-label">THE REASON BEHIND THE RIDE</div><h3>Built from the bigger picture.</h3>${plan.reasons.slice(0, 2).map((r,i) => `<div class="insight-item"><span class="insight-number">0${i+1}</span><p>${esc(r)}</p></div>`).join('')}<div class="section-title"><button class="text-link" data-action="rationale">All assumptions & evidence →</button><span>${esc(POLICY.version)}</span></div></section><section class="card"><div class="small-label">${state.mode === 'synthetic' ? 'SYNTHETIC' : 'RECORDED'} RIDING · LAST 28 DAYS</div><h3>A steady foundation.</h3><p>${a.rides.length} rides · ${duration(a.minutes)} total · ${duration(a.longest)} longest ride</p>${chart(a)}<div class="section-title"><button class="text-link" data-view="history">Explore ride history →</button></div></section></div>
  ${state.revisions.length ? `<div class="section-title"><h2>Plan journal</h2><button class="text-link" data-action="undo">Undo last plan change</button></div>${state.revisions.slice(-3).reverse().map(r => `<div class="revision"><strong>${esc(r.reason)}</strong><p>${esc(r.at)} · ${r.changes.length} workout changes · ${esc(r.id)}</p></div>`).join('')}` : ''}`;
}
function coachCard(plan){
  const c=plan.coach;if(!c)return '<div class="notice">This accepted plan uses an earlier planner. Review a new proposal to use the Coach.</div>';
  return `<section class="card detail-section"><div class="small-label">YOUR COACH · ${esc(plan.version)} · CYCLE WEEK ${c.cycle.week}</div><h2>A purpose for each session.</h2><p>${esc(state.profile.coach?.goalDetail||'Overall improvement, with racing planned from May 2027. Race discipline and exact date still need confirmation.')}</p><div class="metrics"><div><strong>${c.prescription.qualitySessions}</strong><p class="helper">Quality sessions proposed</p></div><div><strong>${Math.round(c.coverage*100)}%</strong><p class="helper">Baseline riding time classified for intensity</p></div><div><strong>${state.profile.bodyMassKg&&state.profile.threshold?(state.profile.threshold.watts/state.profile.bodyMassKg).toFixed(2)+' W/kg':'Not provided'}</strong><p class="helper">Supplied FTP / body mass · estimated when inputs are estimates</p></div></div><p class="helper">${c.ready?'Dated rider feedback supports considering quality work.':'Intervals are conditional on a current readiness check-in and adequate training history.'} Unknown intensity is not counted as easy. Current FTP references do not reconstruct historical thresholds. HR provides context; estimated maximum HR is not a lactate threshold.</p><ul class="helper">${c.reasons.map(r=>`<li>${esc(r)}</li>`).join('')}</ul><details><summary>Four-week cycle outline · conditional, reviewed weekly</summary><ol class="helper">${c.cycle.outline.map(r=>`<li>${esc(r)}</li>`).join('')}</ol><p class="helper">Only this week is prescribed. Future progression depends on execution and recovery; no automatic load increases.</p></details><p class="helper">Evidence: <a href="https://www.stir.ac.uk/research/hub/publication/2095779" target="_blank" rel="noopener noreferrer">2025 intensity-distribution review</a> · <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC13217385/" target="_blank" rel="noopener noreferrer">2026 cycling observations</a>. Practical session doses and safeguards are configurable prototype rules requiring qualified review.</p><button class="text-link" data-view="profile">Update Coach intake & review proposal →</button></section>`;
}
function assessmentCard() {
  const assessment=assessTraining(state.activities,state.profile,today()),b=assessment.baseline;
  const s=assessment.signals;
  return `<section class="card detail-section"><div class="small-label">SIX-MONTH TRAINING PICTURE · ${esc(s.window.start)}–${esc(s.window.end)}</div><h2>${esc(assessment.label)}</h2><div class="metrics"><div><strong>${duration(b.weeklyAverage)}</strong><p class="helper">Pre-recovery baseline / week</p></div><div><strong>${s.measuredPowerRecords} / ${s.cyclingRecords}</strong><p class="helper">Rides reporting measured power</p></div><div><strong>${s.heartRateRecords} / ${s.cyclingRecords}</strong><p class="helper">Rides reporting HR</p></div></div><p class="helper">${esc(assessment.explanation)} Recent baseline: ${esc(addDays(assessment.context.baselineEnd,-27))}–${esc(assessment.context.baselineEnd)}. Longest baseline ride: ${duration(b.longest)}. Confidence: ${esc(assessment.confidence)}.</p><p class="helper">${esc(assessment.missing)}</p>${sensorProgress()}<h3>Observed measured-power benchmarks</h3><div class="table-wrap"><table><thead><tr><th>CONTINUOUS DURATION</th><th>BEST RECORDED POWER</th><th>ACTIVITY DATE</th></tr></thead><tbody>${s.best.map(p=>`<tr><td>${p.seconds<60?p.seconds+' sec':p.seconds/60+' min'}</td><td>${p.watts===null?'Not available / pending':Math.round(p.watts)+' W'+(state.profile.bodyMassKg?' · '+(p.watts/state.profile.bodyMassKg).toFixed(2)+' W/kg':'')}</td><td>${p.date?esc(p.date):'—'}</td></tr>`).join('')}</tbody></table></div><p class="helper">${esc(s.note)} ${s.estimatedPowerRecords} rides report estimated power and are excluded from these benchmarks. W/kg uses your current estimated body mass for every historical effort; it is not historical measured mass. FTP is ${state.profile.threshold?`a supplied ${state.profile.threshold.method} (${state.profile.threshold.watts} W, ${esc(state.profile.threshold.date)})`:'not supplied; no power or HR zones are invented'}.</p>${s.aboveFtpSeconds!==null?`<p class="helper">Last 28 days: approximately ${duration(s.aboveFtpSeconds/60)} above your current FTP reference, using only collected measured-power samples. This is incomplete while collection is pending.</p>`:''}<details><summary>Monthly volume, measured work & recent benchmarks</summary><div class="table-wrap detail-section"><table><thead><tr><th>MONTH</th><th>RIDES</th><th>RIDING TIME</th><th>MEASURED WORK COLLECTED</th></tr></thead><tbody>${s.months.map(m=>`<tr><td>${esc(m.month)}</td><td>${m.rides}</td><td>${duration(m.minutes)}</td><td>${Math.round(m.workKj)} kJ · ${m.measuredWorkRides} rides</td></tr>`).join('')}</tbody></table></div><p class="helper">The first and last months may be partial. Work totals exclude uncollected or estimated-power rides; zero collected work does not mean zero exercise.</p>${s.periods.map(p=>`<p class="helper">${esc(p.label)}: ${p.best20MinuteWatts===null?'no collected 20-minute benchmark':Math.round(p.best20MinuteWatts)+' W best observed over 20 min'} · ${p.recordings} measured-power recordings collected.</p>`).join('')}<p class="helper">${s.steadyComparisons.length} steady recordings support power/HR comparisons. Temperature, trainer setting, hydration, fatigue, and effort selection limit comparisons; no global fitness score is assigned.</p></details>${!stravaStatus.complete?'<div class="notice">The six-month summary scan is incomplete. Treat this assessment and proposal as provisional.</div>':''}${rejectedStrava.length?`<div class="notice">${rejectedStrava.length} records could not be validated for planning. Original records remain visible in Ride history.</div>`:''}<button class="text-link" data-action="rationale">See which rides inform the proposal →</button></section>`;
}
function sensorProgress(){const e=stravaStatus.enrichment;if(!e)return '<div class="notice">Sensor collection requires the updated server. Restart it and reconnect Strava once.</div>';return `<div class="notice ${e.failed?'error':e.pending?'':'success'}"><strong>Detailed collection: ${e.ready} ready · ${e.pending} pending · ${e.unavailable} unavailable · ${e.failed} failed</strong>${stravaStatus.enriching?'A collection batch is running. ':''}${stravaStatus.retryAt?`Strava rate limit: collection resumes after ${esc(new Date(stravaStatus.retryAt).toLocaleString())}. `:''}Collection continues while the server runs. Missing data stays unknown. ${e.failed?'<button class="text-link" data-action="strava-retry-details">Retry failed records</button>':''}</div>`;}
const metric=(value,unit,digits=0)=>value==null?'Not recorded':`${Number(value).toFixed(digits)} ${unit}`;
function activitySensorView(a){
  const reference=state.profile.threshold&&state.profile.threshold.date>=addDays(today(),-POLICY.staleThresholdDays)?state.profile.threshold:null;
  const result=evaluateActivity(a,reference),s=a.sensors,g=a.signals;
  if(!s)return '<p class="helper">Sensor fields have not been imported by this server version.</p>';
  const rows=[['Power source',s.power.source],['Provider average / weighted power',`${metric(s.power.averageWatts,'W')} / ${metric(s.power.weightedWatts,'W')}`],['Provider peak power',metric(s.power.maxWatts,'W')],['HR average / maximum',`${metric(s.heartRate.averageBpm,'bpm')} / ${metric(s.heartRate.maxBpm,'bpm')}`],['Average cadence',metric(s.averageCadence,a.sport.includes('Ride')?'rpm':'cadence units/min')],['Elapsed / moving time',`${s.elapsedSeconds==null?'Unknown':duration(s.elapsedSeconds/60)} / ${duration(a.movingSeconds/60)}`],['Elevation gained',metric(s.elevationMeters,'m')],['Temperature',metric(s.temperatureC,'°C',1)],['Provider work',metric(s.power.workKj,'kJ')],['Measured stream work',metric(g?.workKj,'kJ')],['Provider estimated energy',metric(s.estimatedCalories,'kcal')],['Provider relative effort',metric(s.providerRelativeEffort,'Strava points')],['Trainer / device',`${s.trainer===null?'Unknown':s.trainer?'Indoor / trainer':'Outdoor'} · ${s.deviceName?esc(s.deviceName):'device not reported'}`]];
  return `<h3>Recorded training data</h3><div class="table-wrap"><table><tbody>${rows.map(([k,v])=>`<tr><th>${esc(k)}</th><td>${v}</td></tr>`).join('')}</tbody></table></div><p class="helper">Strava’s weighted power is shown as supplied; it is not relabeled as normalized power. HR zones require an established method and threshold; none is inferred from a ride maximum.</p>${g?`<h3 class="detail-section">Recorded power & HR samples</h3>${signalPlot(g)}<p class="helper">${g.sampleCount} original time points; displayed samples are downsampled. No curve is drawn through missing values. ${g.power.seconds} valid power seconds; ${g.heartRate.seconds} valid HR seconds; ${g.gapSeconds} gap seconds excluded.</p><div class="table-wrap"><table><thead><tr><th>CONTINUOUS EFFORT</th><th>BEST OBSERVED</th></tr></thead><tbody>${g.power.best.map(p=>`<tr><td>${p.seconds<60?p.seconds+' sec':p.seconds/60+' min'}</td><td>${metric(p.watts,'W')}</td></tr>`).join('')}</tbody></table></div>`:''}<h3 class="detail-section">Evaluation & uncertainty</h3><ul class="helper">${[...result.findings,...result.limitations].map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${s.laps?.length?`<details><summary>${s.laps.length} recorded laps / intervals</summary><div class="table-wrap detail-section"><table><thead><tr><th>LAP</th><th>TIME</th><th>AVG POWER</th><th>AVG HR</th></tr></thead><tbody>${s.laps.map(l=>`<tr><td>${esc(l.name)}</td><td>${l.elapsedSeconds==null?'Unknown':duration(l.elapsedSeconds/60)}</td><td>${metric(l.averageWatts,'W')}</td><td>${metric(l.averageBpm,'bpm')}</td></tr>`).join('')}</tbody></table></div><p class="helper">Lap boundaries are provider-recorded. A lap name is not proof of the intended workout or completed prescription.</p></details>`:''}`;
}
function signalPlot(g){
  const maxTime=Math.max(1,g.recordedSeconds),maxPower=Math.max(1,...g.plot.map(p=>p.watts||0)),maxHr=Math.max(1,...g.plot.map(p=>p.bpm||0));
  const points=(key,max,kind)=>g.plot.filter(p=>p[key]!==null).map(p=>{const x=((p.seconds-g.plot[0].seconds)/maxTime*560+30).toFixed(1),y=(170-p[key]/max*140).toFixed(1),title=`<title>${Math.round(p.seconds/60)} min · ${Math.round(p[key])} ${key==='watts'?'W':'bpm'}</title>`;return kind==='power'?`<circle class="signal-power" cx="${x}" cy="${y}" r="2">${title}</circle>`:`<rect class="signal-hr" x="${x}" y="${y}" width="3" height="3">${title}</rect>`;}).join('');
  return `<svg class="signal-plot" viewBox="0 0 620 200" role="img" aria-label="Downsampled power and heart rate samples. Each signal has its own scale: power maximum ${Math.round(maxPower)} watts, HR maximum ${Math.round(maxHr)} bpm. Missing samples are omitted."><path class="signal-axis" d="M30 20V175H590"/>${points('watts',maxPower,'power')}${points('bpm',maxHr,'hr')}<text x="30" y="195">0 min</text><text x="520" y="195">${Math.round(maxTime/60)} min</text></svg><p class="helper">Green dots: power (0–${Math.round(maxPower)} W). Orange squares: HR (0–${Math.round(maxHr)} bpm). Separate scales; visual overlap does not mean the values are equivalent.</p>`;
}
function historyView() {
  const tabs=`<div class="actions detail-section"><button class="btn ${!showLocalHistory?'':'secondary'}" data-action="history-strava" aria-pressed="${!showLocalHistory}">Strava history</button><button class="btn ${showLocalHistory?'':'secondary'}" data-action="history-local" aria-pressed="${showLocalHistory}">Manual / sample records</button></div>`;
  if(showLocalHistory)return tabs+manualHistoryView();
  if(stravaStatus.loading)return tabs+'<div class="empty" role="status"><h2>Loading your Strava history…</h2><p>Checking the current server session.</p></div>';
  if(!stravaStatus.connected)return tabs+`<div class="empty"><h2>Connect Strava to see your rides here.</h2><p>${esc(stravaStatus.error||'Your manual and sample records remain available in the other tab.')}</p><button class="btn" data-view="connection">Open Connections →</button></div>`;
  return tabs+`<div class="page-heading"><div><div class="eyebrow">YOUR ACTUAL TRAINING</div><h1>Ride history, connected.</h1><p>${stravaActivities.length} activities in the last six calendar months · source: Strava API · last sync ${stravaStatus.lastSync?esc(new Date(stravaStatus.lastSync).toLocaleString()):'pending'}</p></div><button class="btn secondary" data-action="strava-sync" ${stravaStatus.syncing?'disabled':''}>Refresh history</button></div>${state.mode==='strava'?assessmentCard():'<div class="notice">Strava records are displayed here; manual coaching inputs are currently selected. <button class="text-link" data-action="coaching-strava">Use Strava for the proposal →</button></div>'}${stravaStatus.error?`<div class="notice error">${esc(stravaStatus.error)}</div>`:''}${stravaActivities.length?`<div class="table-wrap"><table><thead><tr><th>ACTIVITY</th><th>ORIGINAL LOCAL DATE</th><th>MOVING TIME</th><th>DISTANCE</th><th>AVG POWER</th><th>AVG HR</th><th>DETAILS</th></tr></thead><tbody>${stravaActivities.slice(0,stravaVisible).map(a=>`<tr><td><strong>${esc(a.title)}</strong><br><small>${esc(a.sport)} · Strava</small></td><td>${esc(a.localDate)}</td><td>${duration(a.movingSeconds/60)}</td><td>${a.distanceMeters===null?'Unknown':`${(a.distanceMeters/(state.profile.units==='imperial'?1609.344:1000)).toFixed(1)} ${state.profile.units==='imperial'?'mi':'km'}`}</td><td>${a.sensors?metric(a.sensors.power.averageWatts,'W'):'Pending'}<br><small>${esc(a.sensors?.power.source||'unknown source')}</small></td><td>${a.sensors?metric(a.sensors.heartRate.averageBpm,'bpm'):'Pending'}</td><td><button class="text-link" data-action="activity-details" data-id="${esc(a.id)}" aria-label="Details for ${esc(a.title)}">View details</button></td></tr>`).join('')}</tbody></table></div>${stravaActivities.length>stravaVisible?'<button class="btn secondary detail-section" data-action="strava-more">Show more records</button>':''}`:'<div class="empty"><p>No activity summaries yet. A running initial scan must finish before its records appear.</p></div>'}`;
}
function manualHistoryView() {
  const manual=state.mode==='strava'?localState:state;
  if(manual!==state){const current=state;state=manual;try{return manualHistoryView();}finally{state=current;}}
  const a = analyze(state.activities, today());
  const distance = state.activities.filter(r => r.discipline === 'cycling' && r.date >= addDays(today(), -27)).reduce((s,r) => s+(r.distanceKm || 0), 0);
  return `<div class="page-heading"><div><div class="eyebrow">EVERY RIDE TELLS YOU SOMETHING</div><h1>Your riding, in context.</h1><p>${sourceLabel()} history · rolling 28-day analysis</p></div><button class="btn" data-action="add-ride">+ Record a ride</button></div><div class="metrics"><div class="metric"><div class="small-label">RIDING TIME</div><strong>${duration(a.minutes)}</strong><span>${a.rides.length} rides in 28 days</span></div><div class="metric"><div class="small-label">WEEKLY AVERAGE</div><strong>${duration(a.weeklyAverage)}</strong><span>Across all four weeks</span></div><div class="metric"><div class="small-label">DISTANCE</div><strong>${Math.round(distance * (state.profile.units === 'imperial' ? .621371 : 1))} <small>${state.profile.units === 'imperial' ? 'mi' : 'km'}</small></strong><span>Missing distances excluded</span></div></div><div class="notice">Duration describes training volume; it does not establish fitness, FTP, or readiness. RPE is self-reported. ${a.otherMinutes ? `${a.otherMinutes} min of other exercise is considered in the riding budget.` : 'Record other exercise too so the proposal can allow for it.'}</div>${state.activities.length ? `<div class="table-wrap"><table><thead><tr><th>ACTIVITY</th><th>LOCAL DATE</th><th>DURATION</th><th>EFFORT</th><th>SOURCE</th><th><span class="muted">ACTIONS</span></th></tr></thead><tbody>${[...state.activities].sort((a,b) => b.date.localeCompare(a.date)).map(r => `<tr><td><strong>${esc(r.title)}</strong><br><small>${esc(r.discipline)}</small></td><td>${fmtDate(r.date)}</td><td>${duration(r.minutes)}</td><td>${r.rpe === null ? 'Not recorded' : `${r.rpe}/10 RPE`}</td><td><span class="badge">${esc(r.source)}</span></td><td><button class="text-link" data-delete-ride="${esc(r.id)}" aria-label="Delete ${esc(r.title)}">Delete</button></td></tr>`).join('')}</tbody></table></div>` : '<div class="empty"><h2>A fresh start.</h2><p>Record a few recent rides, or start with a gentle plan from your reported riding.</p><button class="btn secondary" data-action="add-ride">Record your first ride</button></div>'}`;
}
function option(value, label, selected) { return `<option value="${esc(value)}" ${value === selected ? 'selected' : ''}>${esc(label)}</option>`; }
function field(name, label, value, attrs = '', hint = '') { return `<label>${esc(label)}<input name="${esc(name)}" value="${esc(value)}" ${attrs}>${hint ? `<small>${esc(hint)}</small>` : ''}</label>`; }
function profileView() {
  const p = state.profile;
  return `<div class="page-heading"><div><div class="eyebrow">YOUR LIFE SETS THE PACE</div><h1>Make this your plan.</h1><p>${state.onboarded ? 'Changes become a proposal for you to review.' : 'A few details help us start conservatively. No sensors required.'}</p></div></div><form id="profile-form" class="profile-form"><section class="form-section"><h3>01 / Where you want to go</h3><p>Your goal gives the week a purpose. Your cycle combines mostly easy riding with goal-specific work when history and recovery support it.</p><div class="form-grid">${field('name','What should we call you? (optional)',p.name,'maxlength="60" autocomplete="given-name"')}<label>Primary goal<select name="goal">${Object.entries({consistency:'Return to consistent riding',fitness:'General fitness',endurance:'Endurance',event:'An event',climbing:'Climbing',racing:'Racing'}).map(([v,l])=>option(v,l,p.goal)).join('')}</select></label><label>Recent riding consistency<select name="experience">${option('new','New to riding',p.experience)}${option('returning','Returning / irregular riding',p.experience)}${option('consistent','Riding consistently',p.experience)}</select></label>${field('weeklyTargetMinutes','Requested weekly cycling volume (minutes)',p.weeklyTargetMinutes ?? '', 'type="number" min="0" max="2400" step="5"', 'Your requested range is 12–13 hours. The first return-week draft targets 720 minutes (12 hours); capacity and recovery can reduce it.')}${field('weeklyMinutes','Typical recent week (minutes)',p.weeklyMinutes,'type="number" min="0" max="2400" step="1" required','Used conservatively if fewer than three recent rides are recorded.')}${field('longestMinutes','Longest recent ride (minutes)',p.longestMinutes,'type="number" min="0" max="2400" step="1" required','Limits individual rides when recorded history is sparse.')}${field('eventDate','Event date (required for an event goal)',p.eventDate,'type="date"')}${field('eventDistanceKm','Event distance, km (optional)',p.eventDistanceKm ?? '', 'type="number" min="1" max="10000"')}<label>Event terrain<select name="eventTerrain">${['mixed','flat','hilly','mountainous'].map(v=>option(v,v,p.eventTerrain)).join('')}</select></label>${field('eventDurationMinutes','Expected event duration, minutes (optional)',p.eventDurationMinutes ?? '', 'type="number" min="1" max="10000"')}</div></section>
  <section class="form-section"><h3>02 / Time that actually works</h3><p>Enter total available minutes, including warm-up and cool-down. Zero means a protected rest day.</p><div class="availability-grid">${DAYS.map((d,i)=>field(`day${i}`,d,p.availability[i],'type="number" min="0" max="360" step="1" required')).join('')}</div><div class="form-grid detail-section">${field('timezone','Local timezone (IANA)',p.timezone,'required','For example America/Toronto. Training dates stay local across daylight-saving changes.')}<label>Preferred units<select name="units">${option('metric','Kilometres',p.units)}${option('imperial','Miles',p.units)}</select></label></div><p class="helper">Other demanding exercise days: we keep these free of additional cycling.</p><div class="check-row">${DAYS.map((d,i)=>`<label><input name="otherDays" type="checkbox" value="${i}" ${p.otherExerciseDays.includes(i)?'checked':''}>${d.slice(0,3)}</label>`).join('')}</div></section>
  <section class="form-section"><h3>03 / Equipment & targets</h3><p>With a dated FTP and power equipment, workouts use watts as the primary target, with a trainer setpoint and cycling-computer range. Estimated maximum HR is context only; it does not define threshold zones.</p><div class="check-row">${Object.entries({bicycle:'Bicycle',trainer:'Indoor trainer',power:'Power meter',hr:'Heart-rate monitor',cadence:'Cadence sensor'}).map(([v,l])=>`<label><input type="checkbox" name="equipment" value="${v}" ${p.equipment.includes(v)?'checked':''}>${l}</label>`).join('')}</div><div class="form-grid detail-section"><label>Riding setting<select name="preference">${option('either','Indoor or outdoor',p.preference)}${option('outside','Outdoor',p.preference)}${option('inside','Indoor',p.preference)}</select></label>${field('ftp','FTP, watts (optional)',p.threshold?.watts ?? '','type="number" min="1" max="1500"')}<label>FTP measurement method<select name="ftpMethod">${option('estimate','Estimate',p.threshold?.method)}${option('test','Test',p.threshold?.method)}</select></label>${field('ftpDate','FTP assessment date',p.threshold?.date || '','type="date"')}</div></section>
  <section class="form-section"><h3>04 / Listen to your body</h3><p>Share only what you want. No medical history is required. We never diagnose from ride data.</p><div class="form-grid">${field('recoveryWeekEnd','Recovery week ends (Sunday)',p.recoveryWeekEnd || '', 'type="date"', 'Your reported recovery week ends November 8; its lighter volume is excluded from the first return-week baseline.')}<label>Current recovery<select name="recovery">${option('normal','Normal / no reduction requested',p.recovery)}${option('poor','Poor recovery / reduce training',p.recovery)}</select></label><label>Training boundary<select name="limitation">${option('none','No restriction reported',p.limitation)}${option('restricted','Illness, injury, pregnancy, rehab, or clinician restriction',p.limitation)}${option('acute','Acute concerning symptoms — pause training',p.limitation)}</select></label></div><p class="helper">Restrictions pause automatic training. Acute symptoms: stop riding and seek urgent medical help; use local emergency services for severe or ongoing symptoms. A prototype cannot provide medical clearance.</p></section>${coachIntake(p)}<div id="profile-error" class="form-error" role="alert"></div><div class="actions"><button class="btn" type="submit">Save inputs & preview proposal →</button><span class="helper">Inputs are saved locally. You decide whether to accept the workouts.</span></div></form>`;
}
function coachIntake(p){
  const c=p.coach||{focus:'endurance',goalDetail:'Overall improvement; racing from May 2027. Discipline and first race date to confirm.',cycleStart:'2026-11-09',checkInDate:today(),fatigue:3,sleep:3,soreness:3,motivation:3,intervalExperience:'unknown',confirmed:false};
  return `<section class="form-section"><h3>05 / Coach & new cycle</h3><p>Confirm how you feel and what you have been doing. Middle ratings below are placeholders until you confirm them. Check in again before each new weekly proposal.</p><div class="form-grid">${field('goalDetail','Your cycle goal and race context',c.goalDetail,'maxlength="500"')}<label>Focus for this cycle<select name="coachFocus">${Object.entries({endurance:'General aerobic development / endurance',sustained:'Sustained power',climbing:'Climbing',race:'Race-specific aerobic power',fitness:'General fitness'}).map(([v,l])=>option(v,l,c.focus)).join('')}</select></label>${field('cycleStart','Cycle starts (Monday)',c.cycleStart,'type="date" required')}${field('checkInDate','Readiness check-in date',c.checkInDate,'type="date" required')}<label>Regular quality sessions before recovery<select name="intervalExperience">${Object.entries({unknown:'Not yet confirmed',none:'None',one:'One per week',two:'Two or more per week'}).map(([v,l])=>option(v,l,c.intervalExperience)).join('')}</select></label>${field('fatigue','Fatigue: 1 low – 5 high',c.fatigue,'type="number" min="1" max="5" required')}${field('soreness','Soreness: 1 low – 5 high',c.soreness,'type="number" min="1" max="5" required')}${field('sleep','Sleep: 1 poor – 5 good',c.sleep,'type="number" min="1" max="5" required')}${field('motivation','Motivation: 1 poor – 5 good',c.motivation,'type="number" min="1" max="5" required')}${field('bodyMassKg','Body mass, kg (optional estimate)',p.bodyMassKg??'','type="number" min="20" max="300" step="0.1"')}${field('maxHeartRate','Estimated maximum HR, bpm (context only)',p.maxHeartRate??'','type="number" min="50" max="260"')}</div><p class="helper">Strength-training days: easy cycling can share these days; quality rides are kept away from them.</p><div class="check-row">${DAYS.map((day,i)=>`<label><input type="checkbox" name="strengthDays" value="${i}" ${(c.strengthDays||[]).includes(i)?'checked':''}>${day.slice(0,3)}</label>`).join('')}</div><label class="check-row detail-section"><input type="checkbox" name="coachConfirmed" ${c.confirmed?'checked':''}>I reviewed the goal, availability, interval experience, recovery ratings, and training boundary above.</label><p class="helper">FTP / body mass describes your supplied estimates, not race category or medical fitness. Estimated maximum HR is not used to infer lactate threshold. Every proposal remains subject to review and acceptance.</p></section>`;
}
function connectionView() {
  const s = stravaStatus;
  return `<div class="page-heading"><div><div class="eyebrow">YOUR HISTORY. YOUR CHOICE.</div><h1>Your Strava connection.</h1><p>Personal REST API connection · client ${esc(s.clientId || '90597')}</p></div><span class="badge">${s.loading ? 'Checking connection…' : s.connected ? 'Connected · read-only' : 'Not connected'}</span></div>
  ${s.error ? `<div class="notice error" role="alert">${esc(s.error)}</div>` : ''}
  <div class="connection-grid"><section class="card"><div class="connection-mark">↗↗</div><h2>One authorization. Regular updates.</h2><p>Connect your own account on Strava’s website. This requests read access to activity records, including activities marked Only You, so private rides are not silently excluded.</p><p class="helper">By connecting, you allow this local server to retrieve activity summaries and refresh them automatically. Only the last six calendar months are collected: activity timing, distance, elevation, recorded HR/power/cadence/temperature, device provenance, laps, and available time-series signals. GPS, route maps, notes, and raw API responses are discarded. Processed training data stays temporary. Nothing is written to Strava.</p>
  ${s.connected ? `<div class="notice success"><strong>${s.syncing ? 'Syncing activity summaries…' : `${s.count || 0} activity summaries available`}</strong>Last successful sync: ${s.lastSync ? esc(new Date(s.lastSync).toLocaleString()) : 'Not yet completed'}.<br>Six-month summary scan: ${s.complete ? 'completed' : 'not complete'}. Sensor detail collection has its own progress below.<br>Next check: ${s.nextSync ? esc(new Date(s.nextSync).toLocaleString()) : 'pending'}.</div><div class="actions"><button class="btn" data-action="strava-sync" ${s.syncing || s.enriching || stravaBusy ? 'disabled' : ''}>Refresh six-month history</button><button class="btn secondary" data-action="strava-disconnect" ${stravaBusy ? 'disabled' : ''}>Disconnect & delete API data</button></div>` : `<button class="btn orange" data-action="strava-connect" ${s.loading || !s.configured || stravaBusy ? 'disabled' : ''}>Connect with Strava ↗</button>${!s.loading && !s.configured ? '<p class="helper">Server credentials are missing. Save .env and restart the Node server.</p>' : ''}`}
  ${s.connected?sensorProgress():''}<p class="helper">Credentials and API records stay in server memory and are lost on restart. The session expires after seven days. Closing the browser does not stop sync while this server and session remain active.</p></section>
  <section class="card"><h2>Know exactly what is connected.</h2><ul class="check-list"><li><strong>Automatic checks:</strong> every 15 minutes for the last 30 days; a daily full scan reconciles older activities and deletions. This is scheduled sync, not instant webhook delivery.</li><li><strong>Activity summaries:</strong> pagination reads accessible activity history. Summary and detailed activity records plus available training streams are collected for the six-month window. This does not download account archives or original FIT files.</li><li><strong>Personal coaching prototype:</strong> Ride history and local planning rules use the retrieved summaries. Estimated training exposure is distinct from measured fitness. Records, derived plans, and evidence are temporary; no Strava data is sent to an AI model, browser storage, or exports.</li><li><strong>Policy boundary:</strong> Strava’s API policy restricts analytics, AI use, and persistent archives. Permission for API-fed coaching remains unresolved; a working OAuth connection does not establish that permission.</li></ul><a href="${stravaConnection.policy}" target="_blank" rel="noopener noreferrer">Review Strava’s API policy ↗</a></section></div>
  <section class="card detail-section"><h3>Instant updates & the official MCP</h3><p class="helper">Strava webhooks need an always-running public callback. This localhost version uses scheduled sync instead; backdated uploads over 30 days old and older edits may take until the daily scan to appear. The official MCP remains the documented personal AI route in eligible assistants; connecting REST here does not connect MCP.</p><div class="actions"><a class="btn secondary" href="${stravaConnection.guide}" target="_blank" rel="noopener noreferrer">Official MCP guide ↗</a><a class="btn secondary" href="https://www.strava.com/settings/apps" target="_blank" rel="noopener noreferrer">Manage Strava access ↗</a></div></section>
  ${s.connected ? `<div class="section-title"><h2>Actual Strava activity records</h2><span>Source: Strava API · temporary display</span></div>${stravaActivities.length ? `<div class="table-wrap"><table><thead><tr><th>ACTIVITY</th><th>LOCAL DATE</th><th>MOVING TIME</th><th>DISTANCE</th></tr></thead><tbody>${stravaActivities.slice(0, stravaVisible).map(a => `<tr><td><a href="https://www.strava.com/activities/${esc(a.id)}" target="_blank" rel="noopener noreferrer">${esc(a.title)}</a><br><small>${esc(a.sport)}</small></td><td>${esc(a.localDate)}</td><td>${duration(Math.round(a.movingSeconds / 60))}</td><td>${a.distanceMeters === null ? 'Unknown' : `${(a.distanceMeters / (state.profile.units === 'imperial' ? 1609.344 : 1000)).toFixed(1)} ${state.profile.units === 'imperial' ? 'mi' : 'km'}`}</td></tr>`).join('')}</tbody></table></div>${stravaActivities.length > stravaVisible ? '<button class="btn secondary detail-section" data-action="strava-more">Show more records</button>' : ''}` : `<div class="empty"><p>${s.syncing ? 'Loading your activity summaries. This can take a little time for a long history.' : 'No activity summaries are available. Check any sync error above, or refresh your history.'}</p></div>`}` : ''}`;
}
function privacyView() {
  return `<div class="page-heading"><div><div class="eyebrow">YOU’RE IN CONTROL</div><h1>Your data stays here.</h1><p>Local browser storage. No account, telemetry, cloud sync, or credentials.</p></div></div><section class="card"><h2>Local storage & retention</h2><p class="helper">Manual/sample activities, your profile, feedback, and manual plan revisions are saved in this browser. Strava records, derived plans, and their feedback/revisions stay in memory and clear on reload or disconnect. They are not encrypted; anyone with access to this browser profile can read them. Use your own device. Clearing browser data removes the app’s records. Private browsing may discard them.</p><label>Activity retention<select id="retention">${[30,90,365].map(d=>option(String(d),`${d} days`,String(state.profile.retentionDays))).join('')}</select><small>On save and next load, older activity records are removed. Plans and their evidence IDs remain until you delete all data; ride titles and raw activity data are not copied into revisions.</small></label><div class="actions detail-section"><button class="btn secondary" data-action="retention">Save retention setting</button><button class="btn secondary" data-action="export">Export my local data</button><button class="btn danger" data-action="delete-data">Delete all local data</button></div><p class="helper">Export downloads a JSON snapshot that may contain personal training information. Store it securely. No import feature is enabled. Browser backups and downloaded exports must be deleted separately.</p>${loadError ? '<button class="btn secondary" data-action="export-raw">Download unreadable saved data</button>' : ''}</section><section class="card detail-section"><h3>Credentials & Strava</h3><p class="helper">Do not paste API tokens, OAuth codes, or passwords here. Browser coaching storage holds no Strava credentials. The personal REST connection keeps tokens and temporary activity summaries only in server memory. Authorize on Strava’s own page in Connections. Disconnect there to delete API data and revoke access; external MCP assistants must be managed separately.</p><button class="text-link" data-view="connection">Connection & revocation instructions →</button></section>`;
}
function preview(profile = state.profile, reason = 'Weekly plan reviewed') {
  try {
    const activities=state.mode==='strava'?[...fromStrava(stravaActivities,profile.timezone,localDate(profile.timezone)).activities,...state.activities.filter(a=>a.source==='manual')]:state.activities;
    const plan = propose(profile, activities, localDate(profile.timezone), state.plan, planningContext(profile,localDate(profile.timezone)));
    const diff = changes(state.plan, plan);
    pending = { id: crypto.randomUUID(), mode: state.mode, profile: structuredClone(profile), plan, reason, diff, baseRevision: state.revision };
    openModal(`${modalHeading('Your week, with room to breathe.', 'Review the proposal before changing your plan.')}<span class="badge">${sourceLabel()} evidence · ${esc(plan.version)}</span><div class="workout-stats"><div><strong>${duration(plan.total)}</strong><span>Total planned time</span></div><div><strong>${plan.workouts.filter(w=>w.minutes).length}</strong><span>Rides · ${plan.workouts.filter(w=>isQualityWorkout(w)).length} quality</span></div></div>${plan.conflicts.length ? `<div class="notice error"><strong>Resolve conflicts before accepting</strong>${plan.conflicts.map(esc).join('<br>')}</div>` : ''}<h3>Why this proposal?</h3><ul class="helper">${plan.reasons.map(r=>`<li>${esc(r)}</li>`).join('')}</ul><h3>Workout details before acceptance</h3>${plan.workouts.filter(w=>w.minutes).map(w=>`<details class="detail-section"><summary>${esc(w.date)} · ${esc(w.title)} · ${w.minutes} min</summary><p class="helper">${esc(w.purpose)}</p>${deviceSetupView(w,'proposal')}<ol class="helper">${w.steps.map(s=>`<li>${esc(s.title)}: ${s.minutes} min at ${stepTargetLabel(s)}. ${esc(s.guidance)}</li>`).join('')}</ol><p class="helper">Easier option: ${esc(w.alternative)}</p></details>`).join('')}<h3>What changes</h3>${diff.length ? diff.map(c=>`<div class="diff"><strong>${fmtDate(c.date)}</strong><span><small>BEFORE</small>${esc(c.before)}</span><span><small>PROPOSED</small>${esc(c.after)}</span></div>`).join('') : '<p class="helper">Workout durations and titles stay the same. Updated settings and rationale will be saved.</p>'}<p class="helper">Completed, partial, skipped, modified, and locked sessions are preserved. Missed workouts are never added to another day. Policy limits are unvalidated prototype rules.</p><div class="detail-actions"><button class="btn" data-action="accept" ${plan.conflicts.length ? 'disabled' : ''}>Accept proposal →</button><button class="btn secondary" data-action="close">Keep current plan</button></div>`);
  } catch (e) { const error = $('#profile-error'); if (error) { error.textContent = e.message; error.scrollIntoView({ block:'center' }); } else notify(e.message); }
}
function showWorkout(id) {
  const plan = currentPlan(), w = plan.workouts.find(w=>w.id===id); if (!w) return;
  openModal(`${modalHeading(w.title, `${fmtDate(w.date, {weekday:'long',month:'long',day:'numeric'})} · ${w.timezone}`)}<div class="detail-meta"><span class="badge">${w.minutes} min planned</span><span class="badge">${w.minutes ? (w.steps[0]?.unit==='W'?'Watts · FTP reference':'RPE targets') : 'Rest'}</span><span class="badge">${esc(state.plan ? w.status : 'Proposal')}</span>${w.locked ? '<span class="badge">◆ Locked</span>' : ''}</div><p class="helper">${esc(w.purpose)}</p>${deviceSetupView(w,'current')}${w.steps.map((s,i)=>`<div class="step"><span class="step-index">${i+1}</span><div><strong>${esc(s.title)}</strong><p>${esc(s.guidance)}</p></div><strong>${s.minutes} min · ${stepTargetLabel(s)}</strong></div>`).join('')}<div class="detail-section"><h3>An easier option</h3><p>${esc(w.alternative)}</p></div><div class="detail-section"><h3>Why this is here</h3><p>${esc(w.explanation||plan.reasons[0])}</p><p>Goal: ${esc(goalLabel())}. Available on this day: ${state.profile.availability[weekday(w.date)]} min. Target method: ${esc(w.targetMethod)}. Equipment: ${w.equipment.map(esc).join(', ') || 'none'}. ${w.thresholdVersion?`Threshold snapshot: ${esc(w.thresholdVersion)}. Watt targets use the preserved provisional FTP. Reduce the target or stop if recovery or symptoms change.`:`No FTP threshold is used.`}</p><button class="text-link" data-action="rationale">View all evidence & assumptions →</button></div>${w.feedback ? `<div class="notice success"><strong>Recorded ${esc(w.status)}</strong>${w.feedback.actualMinutes} actual minutes · felt ${esc(w.feedback.feeling)}. Original prescription is preserved.${w.activityId ? ` Matched activity: ${esc(w.activityId)}.` : ''}</div>` : ''}<div class="detail-actions">${state.plan && w.status === 'planned' ? `<button class="btn" data-feedback="${esc(w.id)}" ${w.date > today() ? 'disabled' : ''}>Record outcome</button><button class="btn secondary" data-lock="${esc(w.id)}">${w.locked ? 'Unlock' : 'Lock'} session</button>` : !state.plan ? '<button class="btn" data-action="setup">Set up & review plan →</button>' : ''}<button class="btn secondary" data-action="close">Close</button></div>${w.date > today() ? '<p class="helper">Future sessions can be locked; outcomes can be recorded on or after the planned day.</p>' : ''}`);
}
function stepTargetLabel(s){return s.unit==='W'?`${s.target} W · range ${s.powerTarget.minWatts}–${s.powerTarget.maxWatts} W · ${(s.target/s.powerTarget.thresholdWatts*100).toFixed(1)}% FTP`:`RPE ${s.target}/10`;}
function strengthWeek(){const currentStart=addDays(today(),weekday(today())===0?-6:1-weekday(today()));const current=state.strengthRoom.plans.some(p=>p.startDate===currentStart);const start=strengthSelectedWeek||(current?currentStart:planningContext(state.profile,today()).startDate);const previous=[...state.strengthRoom.plans].reverse().find(p=>p.startDate===start);return {draft:strengthProposal(state.profile,start,state.strengthRoom.records,previous,today()),accepted:previous};}
function strengthView(){
  const c=state.profile.strength||defaultStrengthSettings(),{draft,accepted}=strengthWeek(),plan=accepted||draft;
  return `<div class="page-heading"><div><div class="eyebrow">STRENGTH SUPPORTS THE RIDE</div><h1>Your strength room.</h1><p>Thursday and Sunday · ${esc(plan.startDate)}–${esc(addDays(plan.startDate,6))} · ${esc(state.profile.timezone)}</p></div><span class="badge">${accepted?'Accepted prescription':draft.canAccept?'Proposal · not accepted':'Draft · setup or restriction review'}</span></div><div class="notice"><strong>Gym time is separate from your 12-hour cycling availability.</strong>Thursday is the main session. Sunday uses a smaller dose after Saturday’s long ride. No lifting load is inferred from FTP or Strava HR/power. Sets should finish with at least 3 clean repetitions still available; this is a lifting-load instruction, not a cycling RPE target.</div><form id="strength-settings" class="form-section"><h3>Your strength setup</h3><div class="actions">${[...new Set(state.strengthRoom.plans.map(p=>p.startDate)),planningContext(state.profile,today()).startDate].filter((v,i,a)=>a.indexOf(v)===i).sort().slice(-8).map(date=>`<button type="button" class="text-link" data-action="strength-week" data-start="${date}">Week of ${date}</button>`).join('')}</div><div class="form-grid"><label>Equipment<select name="equipment">${option('gym','Full gym',c.equipment)}${option('dumbbells','Dumbbells / home gym',c.equipment)}${option('bodyweight','Bodyweight / stable chair and floor',c.equipment)}</select></label><label>Recent strength experience<select name="experience">${option('unknown','Not confirmed',c.experience)}${option('new','New or restarting these movements',c.experience)}${option('regular','Already doing these movements regularly',c.experience)}</select></label>${field('thursdayMinutes','Thursday gym availability, minutes',c.thursdayMinutes,'type="number" min="15" max="90" required')}${field('sundayMinutes','Sunday gym availability, minutes',c.sundayMinutes,'type="number" min="15" max="90" required')}<label>Movement restrictions<select name="restrictions">${option('unknown','Not confirmed',c.restrictions)}${option('none','No painful movements or restrictions reported',c.restrictions)}${option('restricted','Pain, injury, or restrictions — pause prescriptions',c.restrictions)}</select></label>${field('loadNotes','Reported lifting references (keep units and total/per-side distinction)',c.loadNotes||'','maxlength="1000"')}</div><label class="check-row"><input name="confirmed" type="checkbox" ${c.confirmed?'checked':''}>I reviewed equipment, separate gym time, experience, and restrictions.</label><p class="helper">First-cycle doses are introductory. If an exercise is unfamiliar, practise unloaded and obtain in-person technique guidance before adding weight. Rest, sharp pain, and restrictions take priority.</p><div class="actions"><button class="btn secondary" type="submit">Save setup & preview strength week →</button>${!accepted?`<button type="button" class="btn" data-action="strength-review">Review these two sessions →</button>`:''}</div><div id="strength-error" class="form-error" role="alert"></div></form>${plan.reasons.map(r=>`<p class="helper">${esc(r)}</p>`).join('')}${accepted?'<div class="actions"><button class="btn secondary" data-action="strength-review">Review changed strength proposal</button><button class="text-link" data-action="strength-undo">Undo future strength change</button></div>':''}<div class="strength-grid">${plan.sessions.map(s=>strengthSessionView(s,Boolean(accepted))).join('')}</div><section class="card detail-section"><h3>How this fits the cycling cycle</h3><p class="helper">Keep the same-day cycling prescription easy. Separate gym and riding by roughly 3 hours when feasible. Sunday follows a long ride, so use the lighter option if legs remain unusually heavy. Strength frequency and total volume may need revision after your equipment and history are confirmed. Avoid introducing extra gym work beyond what you have been doing while also increasing cycling load.</p><p class="helper">Evidence: <a href="https://pubmed.ncbi.nlm.nih.gov/40632222/" target="_blank" rel="noopener noreferrer">2026 strength-training review</a>. These exercise selections and introductory doses are transparent prototype choices, not a validated individual strength programme.</p></section>`;
}
function strengthSessionView(s,accepted){
  const record=state.strengthRoom.records.find(r=>r.sessionId===s.id);
  return `<section class="card strength-session"><div class="small-label">${esc(s.date)} · ${esc(s.timezone)}</div><h2>${esc(s.title)}</h2><span class="badge">${s.minutes} min planned / ${s.availableMinutes} min available</span><p>${esc(s.purpose)}</p>${s.loadNotes?`<p class="helper"><strong>Your reported references:</strong> ${esc(s.loadNotes)}</p>`:''}${s.paused?'<div class="notice error">No strength work is prescribed under the current restrictions or time constraints.</div>':`<div class="notice ${s.ready?'success':''}"><strong>${s.reduced?'Reduced sets for recovery':s.ready?'Ready for review':'Illustrative draft — setup not confirmed'}</strong>Exercise block times include sets, recovery, and setup. They are estimates, not a countdown to rush through.</div><h3>1. Warm up · ${s.warmup.minutes} min</h3><p class="helper">${esc(s.warmup.instructions)}</p>${s.exercises.map((e,i)=>`<details class="strength-exercise" open><summary>${i+2}. ${esc(e.title)} · ${e.sets} × ${esc(e.reps)}</summary><p class="helper"><strong>Rest:</strong> ${e.restSeconds} seconds between sets. For unilateral exercises, finish both sides before the rest; switch sides with a brief reset. Complete all sets before moving on. Approximate block: ${e.minutes} min.</p><p class="helper"><strong>Load:</strong> ${esc(e.load)}</p><ol class="helper">${e.cues.map(c=>`<li>${esc(c)}</li>`).join('')}</ol><p class="helper"><strong>Execution:</strong> ${esc(e.tempo)}</p><p class="helper"><strong>Easier substitution:</strong> ${esc(e.alternative)}</p></details>`).join('')}<h3>${s.exercises.length+2}. Finish · ${s.cooldown.minutes} min</h3><p class="helper">${esc(s.cooldown.instructions)}</p><details><summary>Coordinate, progress, or make it easier</summary><p class="helper">${esc(s.coordination)}</p><p class="helper">${esc(s.progression)}</p><p class="helper">${esc(s.easier)}</p></details>`}${record?`<div class="notice success"><strong>Recorded ${esc(record.status)}</strong>${record.actualMinutes} min · soreness ${record.soreness}/5 · ${record.pain?'pain reported':'no pain reported'}<br>${esc(record.notes)}</div>`:''}${accepted&&!record&&!s.paused?`<button class="btn secondary" data-action="strength-feedback" data-id="${esc(s.id)}" ${s.date>today()?'disabled':''}>Record completed / partial / modified / skipped</button>${s.date>today()?'<p class="helper">Record outcomes on or after the session day.</p>':''}`:''}</section>`;
}
function reviewStrength(){const {draft,accepted}=strengthWeek();openModal(`${modalHeading('Review Thursday & Sunday strength.','Cycling prescriptions remain subject to their own review.')}<p class="helper">${draft.reasons.map(esc).join(' ')}</p>${draft.sessions.map(s=>`<div class="revision"><strong>${esc(s.title)} · ${esc(s.date)}</strong><p class="helper">${s.minutes} min · ${s.exercises.map(e=>`${esc(e.title)}: ${e.sets} × ${esc(e.reps)}`).join('; ')}</p></div>`).join('')}<p class="helper">${accepted?'Previously completed or past prescriptions are preserved. Future uncompleted sessions will use the reviewed setup.':'No sessions are marked completed by acceptance.'} No automatic progression or missed-work catch-up.</p><button class="btn" data-action="strength-accept" ${draft.canAccept?'':'disabled'}>Accept strength week</button><button class="btn secondary" data-action="close">Keep current prescription</button>`);}
function deviceSetupView(w,source){
  if(!w.minutes||w.steps.some(s=>s.unit!=='W'))return '';
  const d=deviceWorkout(w),clock=n=>`${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`;
  return `<section class="detail-section"><h3>Computer / trainer setup</h3><p class="helper">FTP assumption: <strong>${d.ftpWatts} W</strong> · ${esc(d.thresholdDate)} · total ${clock(d.totalSeconds)} (minutes:seconds). Create a cycling workout with timed steps and custom power targets. Each row below is one step; all repetitions are expanded.</p><div class="table-wrap"><table><thead><tr><th>STEP / PURPOSE</th><th>DURATION</th><th>TRAINER SETPOINT</th><th>OUTDOOR RANGE</th><th>ELAPSED END</th></tr></thead><tbody>${d.rows.map(r=>`<tr><td>${r.step}. ${esc(r.title)}</td><td>${clock(r.seconds)}</td><td>${r.watts} W · ${r.ftpPercent.toFixed(1)}% FTP</td><td>${r.minWatts}–${r.maxWatts} W</td><td>${clock(r.endSeconds)}</td></tr>`).join('')}</tbody></table></div><p class="helper">Computer: use Time for duration, Custom Power in watts for the target, and automatic step advance. Trainer: enter the fixed setpoints. For Zwift, set FTP to ${d.ftpWatts} W and workout intensity to 100%; its file stores relative power and will rescale if FTP changes. Stop or reduce the workout when recovery changes.</p><div class="actions"><button class="btn secondary" data-action="download-workout" data-format="zwo" data-id="${esc(w.id)}" data-source="${source}">Download Zwift .zwo</button><button class="btn secondary" data-action="download-workout" data-format="txt" data-id="${esc(w.id)}" data-source="${source}">Download setup instructions</button></div><p class="helper">Downloads contain this prescription and its FTP reference. Importing or entering it into a device is your choice. Direct computer synchronization and FIT export are not implemented.</p></section>`;
}
function rationale() {
  const p = currentPlan();
  openModal(`${modalHeading('A plan you can understand.', 'The observations and assumptions behind this week.')}<span class="badge">${sourceLabel()} · ${esc(p.version)}</span><ul class="helper">${p.reasons.map(r=>`<li>${esc(r)}</li>`).join('')}</ul><h3>Activity evidence</h3><p class="helper">Evidence captured when this proposal was generated. Deleted or expired records are marked unavailable. Duration is not a fitness measurement.</p>${p.evidenceIds.length ? p.evidenceIds.map(id=>{const a=state.activities.find(r=>r.id===id);return `<div class="revision">${a ? `<strong>${esc(a.title)}</strong><p>${esc(a.date)} · ${a.minutes} min · ${esc(a.source)} · ${esc(a.id)}</p>` : `${esc(id)} — unavailable (deleted or expired)`}</div>`;}).join('') : '<p class="helper">No recorded history used. Reported weekly time and a conservative cap were used.</p>'}<div class="notice">The Coach uses deterministic, evidence-informed rules. Session doses and progression safeguards are not individually validated; qualified review is still required before production. A proposed week is not a fitness test or medical clearance.</div><button class="btn secondary" data-action="close">Close</button>`);
}
function recordRide() {
  if (state.mode === 'synthetic') { switchManual(); return; }
  openModal(`${modalHeading('Record a ride or other exercise.', 'This is your own manual record, not a Strava import.')}<form id="ride-form"><div class="form-grid">${field('title','Activity name','','required maxlength="100"')}${field('date','Local date',today(),`type="date" required max="${today()}"`)}${field('minutes','Moving time, minutes','','type="number" min="1" max="1440" step="1" required')}${field('distance','Distance (optional)', '', 'type="number" min="0" max="2000" step="0.1"', state.profile.units === 'imperial' ? 'Miles; stored internally as kilometres.' : 'Kilometres.')}${field('rpe','Perceived effort, 1–10 (optional)','','type="number" min="1" max="10" step="1"')}<label>Discipline<select name="discipline"><option value="cycling">Cycling</option><option value="other">Other exercise</option></select></label></div><p class="helper">Record only your own observations. Missing effort or distance stays unknown. Saving a ride does not automatically change the plan; review a new proposal after saving.</p><div class="form-error" id="ride-error" role="alert"></div><button class="btn" type="submit">Save activity</button></form>`);
}
function switchManual() {
  if (state.mode==='strava') {useStravaCoaching=false;state=localState;view='history';showLocalHistory=true;$('#modal').close();render();return;}
  if (state.mode === 'manual') { view='history'; $('#modal').close(); render(); return; }
  openModal(`${modalHeading('Start with your own history.', 'Synthetic data will be removed so it cannot influence your personal plan.')}<p class="helper">This removes the fictional rides, example workouts, and example revision history. Your goal and availability settings stay. You can then record real rides manually and review a fresh proposal.</p><div class="detail-actions"><button class="btn" data-action="confirm-manual">Remove examples & start</button><button class="btn secondary" data-action="close">Keep exploring</button></div>`);
}
function feedbackForm(id) {
  const w=state.plan?.workouts.find(w=>w.id===id); if (!w || w.status!=='planned' || w.date>today()) return;
  const candidates=state.activities.filter(a=>a.date===w.date && a.discipline==='cycling' && !state.plan.workouts.some(v=>v.activityId===a.id));
  openModal(`${modalHeading('How did it go?', 'Your original workout stays intact. Actual activity is stored separately.')}<form id="feedback-form" data-id="${esc(id)}"><div class="form-grid"><label>Outcome<select name="status"><option value="completed">Completed</option><option value="partial">Partial</option><option value="modified">Modified</option><option value="skipped">Skipped</option></select></label>${field('actualMinutes','Actual time, minutes',w.minutes,'type="number" min="0" max="1440" step="1" required')}<label>How it felt<select name="feeling"><option value="comfortable">Comfortable</option><option value="hard">Harder than expected</option><option value="poor">Poor recovery — ease off</option></select></label><label>Match an existing activity (optional)<select name="activityId"><option value="">Create a separate manual activity</option>${candidates.map(a=>option(a.id,`${a.title} · ${a.minutes} min`,'')).join('')}</select></label></div><p class="helper">For skipped sessions, enter zero minutes. An existing match must have the same duration you report. Poor recovery is saved immediately; plan changes still need review.</p><div class="form-error" id="feedback-error" role="alert"></div><button class="btn" type="submit">Save outcome & review next steps →</button></form>`);
}
function download(text, name) { const url=URL.createObjectURL(new Blob([text],{type:'application/json'})); const link=document.createElement('a'); link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000); }
document.addEventListener('click', async e => {
  const b=e.target.closest('button[data-view],button[data-action],button[data-workout],button[data-recovery],button[data-lock],button[data-feedback],button[data-delete-ride]'); if (!b) return;
  if (b.dataset.view) { view=b.dataset.view; render(); return; }
  if (b.dataset.workout) return showWorkout(b.dataset.workout);
  if (b.dataset.recovery) { selectedRecovery=b.dataset.recovery;render();return; }
  if (b.dataset.feedback) return feedbackForm(b.dataset.feedback);
  if (b.dataset.lock) { if (commit(s=>{const w=s.plan.workouts.find(w=>w.id===b.dataset.lock);w.locked=!w.locked;})) showWorkout(b.dataset.lock);return; }
  if (b.dataset.deleteRide) {
    const id=b.dataset.deleteRide;
    openModal(`${modalHeading('Delete this activity?')}<p class="helper">It will no longer inform new proposals. Accepted workout prescriptions remain; any match to this activity is removed.</p><button class="btn danger" data-action="confirm-delete-ride" data-id="${esc(id)}">Delete activity</button>`);return;
  }
  const action=b.dataset.action;
  if(action==='strength-undo'){const {accepted}=strengthWeek();if(accepted&&commit(s=>{if(!undoStrengthWeek(s.strengthRoom,accepted.startDate,today()))throw Error('There are no future strength changes to undo.');}))notify('Future strength change undone; completed prescriptions and feedback are preserved.');return;}
  if(action==='strength-week'){strengthSelectedWeek=b.dataset.start;render();return;}
  if(action==='strength-review'){reviewStrength();return;}
  if(action==='strength-accept'){
    const {draft,accepted}=strengthWeek();if(!draft.canAccept)return notify('Confirm the strength setup and resolve restrictions first.');
    if(accepted&&JSON.stringify(accepted.sessions)===JSON.stringify(draft.sessions)){notify('This strength prescription is already accepted.');$('#modal').close();return;}
    if(commit(s=>{const revision=(accepted?.revision??-1)+1;s.strengthRoom.plans.push({...structuredClone(draft),revision,acceptedAt:new Date().toISOString()});s.strengthRoom.plans=s.strengthRoom.plans.slice(-52);})){ $('#modal').close();notify('Strength week accepted. No completed workouts were changed.');}return;
  }
  if(action==='strength-feedback'){
    const session=strengthWeek().accepted?.sessions.find(s=>s.id===b.dataset.id);if(!session||session.date>today())return;
    openModal(modalHeading('Record strength training.',session.title+' · '+session.date)+'<form id="strength-feedback" data-id="'+esc(session.id)+'"><div class="form-grid"><label>Outcome<select name="status"><option value="completed">Completed</option><option value="partial">Partial</option><option value="modified">Modified</option><option value="skipped">Skipped</option></select></label>'+field('actualMinutes','Actual strength time, minutes',session.minutes,'type="number" min="0" max="180" required')+field('soreness','Soreness: 1 low – 5 high',1,'type="number" min="1" max="5" required')+'<label>Any pain during these movements?<select name="pain"><option value="no">No</option><option value="yes">Yes — pause strength and review restrictions</option></select></label>'+field('notes','Actual exercises, sets/reps, and weights (kg), or modifications','','maxlength="1000"')+'</div><p class="helper">High soreness reduces future proposals; reported pain pauses automatic strength and cycling until the training boundary is reviewed. This does not diagnose an injury. Imported Strava weight-training records are not duplicated by this feedback.</p><div class="form-error" id="strength-feedback-error" role="alert"></div><button class="btn" type="submit">Save actual training</button></form>');return;
  }

  if(action==='download-workout'){
    try{const plan=b.dataset.source==='proposal'?pending?.plan:currentPlan(),w=plan?.workouts.find(w=>w.id===b.dataset.id);if(!w)throw Error('Review the workout again before downloading.');const zwo=b.dataset.format==='zwo';const body=zwo?workoutZwo(w):workoutSetupText(w);const url=URL.createObjectURL(new Blob([body],{type:zwo?'application/xml':'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=w.date+'-'+w.id+(zwo?'.zwo':'.txt');a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Workout prescription downloaded. Check the FTP setting before importing it.');}catch(e){notify(e.message);}return;
  }
  if(action==='history-local'||action==='coaching-local'){useStravaCoaching=false;state=localState;showLocalHistory=true;render();return;}
  if(action==='history-strava'||action==='coaching-strava'){showLocalHistory=false;useStravaCoaching=true;applyStravaRecords();render();if(!stravaStatus.connected)notify('Connect Strava first.');return;}
  if(action==='activity-details'){
    const a=stravaActivities.find(a=>a.id===b.dataset.id);if(!a)return;
    const assessment=assessTraining(state.mode==='strava'?state.activities:fromStrava(stravaActivities,state.profile.timezone,today()).activities,state.profile,today());
    const used=assessment.evidenceIds.includes(`strava-${a.id}`);
    openModal(`${modalHeading(a.title,`${a.sport} · actual Strava record`)}<div class="detail-meta"><span class="badge">${duration(a.movingSeconds/60)} moving time</span><span class="badge">${esc(a.localDate)} original local date</span><span class="badge">Strava API</span></div><p class="helper">${used?'This ride contributes to the four-week baseline used for the next proposal.':'This activity is outside the cycling baseline window, zero-duration, or another sport. Other exercise is considered separately.'} It is not assumed to match a planned workout.</p><p class="helper">Original start instant: ${esc(a.startDate)}. Dates used in planning follow ${esc(state.profile.timezone)}. Distance: ${a.distanceMeters===null?'unknown':`${(a.distanceMeters/1000).toFixed(1)} km`}. Recorded sensor metrics and lap execution are evaluated below; missing data is not invented.</p>${activitySensorView(a)}<div class="actions"><button class="btn secondary" data-action="activity-details" data-id="${esc(a.id)}">Refresh these details</button><a class="btn secondary" href="https://www.strava.com/activities/${esc(a.id)}" target="_blank" rel="noopener noreferrer">View original on Strava ↗</a><button class="btn secondary" data-action="close">Close</button></div>`);return;
  }
  if(action?.startsWith('strava-')) {
    if(action==='strava-more'){stravaVisible+=50;render();return;}
    if(stravaBusy)return;
    stravaBusy=true;render();
    try {
      if(action==='strava-connect'){const result=await stravaRequest('connect');location.assign(result.authorizationUrl);return;}
      if(action==='strava-sync'){await stravaRequest('sync');notify('Six-month history refresh started.');} if(action==='strava-retry-details'){await stravaRequest('retry-details');notify('Detail collection retry started.');}
      if(action==='strava-disconnect'){const result=await stravaRequest('disconnect');stravaActivities=[];notify(result.message);}
      await refreshStrava();
    }catch(error){notify(error.message);}finally{stravaBusy=false;render();}
    return;
  }
  if (action==='close') return $('#modal').close();
  if (action==='setup') { $('#modal').close();view='profile';render();window.scrollTo(0,0); }
  if (action==='rebuild') state.onboarded ? preview() : (view='profile',render());
  if (action==='rationale') rationale();
  if (action==='recovery-preview') { if(!selectedRecovery) return notify('Choose how you feel first.'); if(!state.onboarded) { view='profile';render();notify('Set up your goals and availability first.');return; } preview({...state.profile,recovery:selectedRecovery},'Recovery check-in'); }
  if (action==='accept' && pending) {
    const p=pending;
    if(p.mode!==state.mode)return notify('The history source changed. Close this preview and review a proposal using the current source.');
    if(p.baseRevision!==state.revision) return notify('Your data changed while this proposal was open. Close and create a fresh preview.');
    if(p.plan.conflicts.length) return;
    if(commit(s=>{if(s.mode==='strava')s.activities=[...fromStrava(stravaActivities,p.profile.timezone,localDate(p.profile.timezone)).activities,...s.activities.filter(a=>a.source==='manual')];acceptProposal(s,p);})) {pending=null;$('#modal').close();view='week';render();notify(state.mode==='strava'?'Proposal accepted for this temporary Strava workspace. Reloading clears it.':'Proposal accepted. Your plan is saved on this device.');}
  }
  if(action==='undo') {
    const r=[...state.revisions].reverse().find(r=>!r.undone && r.reason!=='Undo future plan change');
    if(!r) return notify('No plan change remains to undo.');
    openModal(`${modalHeading('Undo the last plan change?')}<p class="helper">${esc(r.reason)} will be reversed for future, unlocked workouts. Recorded outcomes and locks stay. Goal, availability, and recovery settings will stay current; review another proposal to reconcile them.</p><button class="btn" data-action="confirm-undo" data-id="${esc(r.id)}">Undo future changes</button>`);
  }
  if(action==='confirm-undo') {
    if(commit(s=>{const r=s.revisions.find(r=>r.id===b.dataset.id);if(!r || r.undone) return;const before=structuredClone(s.plan);if(!r.before) {if(s.plan.workouts.some(w=>w.status!=='planned'||w.locked)) throw Error('Initial plan has recorded or locked sessions and cannot be removed.');s.plan=null;}else s.plan=restoreFuture(s.plan,r.before,today());r.undone=true;s.revisions.push({id:crypto.randomUUID(),at:new Date().toISOString(),reason:'Undo future plan change',before,after:structuredClone(s.plan),changes:s.plan?changes(before,s.plan):[]});s.revisions=s.revisions.slice(-100);} )){$('#modal').close();notify('Future changes undone; settings and recorded outcomes were preserved.');}
  }
  if(action==='switch-manual') switchManual();
  if(action==='confirm-manual') {if(commit(s=>{s.mode='manual';s.activities=[];s.plan=null;s.revisions=[];s.processedEvents=[];})){$('#modal').close();view='history';render();notify('Examples removed. Record your own rides to personalize the plan.');}}
  if(action==='add-ride') recordRide();
  if(action==='confirm-delete-ride') {if(commit(s=>{s.activities=s.activities.filter(a=>a.id!==b.dataset.id);for(const p of [s.plan,...s.revisions.flatMap(r=>[r.before,r.after])].filter(Boolean)) for(const w of p.workouts) if(w.activityId===b.dataset.id)w.activityId=null;})){$('#modal').close();notify('Activity deleted. Review a new proposal to update the plan.');}}
  if(action==='export') {download(JSON.stringify(localState,null,2),'cadence-local-export.json');if(state.mode==='strava')notify('Export includes manual/profile data only. Temporary Strava records and plans are excluded.');}
  if(action==='export-raw') download(localStorage.getItem(KEY)||'null','cadence-unreadable-backup.json');
  if(action==='retention') {if(commit(s=>{s.profile.retentionDays=Number($('#retention').value);s.activities=s.activities.filter(a=>a.source==='strava'||a.date>=addDays(today(),-s.profile.retentionDays));}))notify('Activity retention saved. Older activity records removed.');}
  if(action==='delete-data') openModal(`${modalHeading('Delete all local app data?')}<p class="helper">This permanently removes your local profile, rides, feedback, and plans from this browser. Download an export first if you need it. External Strava connections are managed separately.</p><button class="btn danger" data-action="confirm-delete">Delete all local data</button>`);
  if(action==='confirm-delete') {try{if(stravaStatus.connected){const result=await stravaRequest('disconnect');if(!result.revoked)notify(result.message);stravaActivities=[];await refreshStrava();}localStorage.removeItem(KEY);loadError='';state=initialState();state.mode='manual';state.activities=[];localState=state;stravaWorkspace=null;view='privacy';$('#modal').close();render();notify('Local coaching data and this session’s API cache deleted. External access is managed in Strava My Apps.');}catch(e){notify(e.message);}}
});
document.addEventListener('submit',e=>{
  e.preventDefault();const f=e.target,d=new FormData(f);

  if(f.id==='strength-settings'){
    const c={equipment:d.get('equipment'),experience:d.get('experience'),thursdayMinutes:Number(d.get('thursdayMinutes')),sundayMinutes:Number(d.get('sundayMinutes')),restrictions:d.get('restrictions'),confirmed:d.has('confirmed'),loadNotes:String(d.get('loadNotes')||'').trim()};
    if(commit(s=>{s.profile.strength=c;if(s.profile.coach)s.profile.coach.strengthDays=[4,0];}))reviewStrength();return;
  }
  if(f.id==='strength-feedback'){
    const session=strengthWeek().accepted?.sessions.find(s=>s.id===f.dataset.id);if(!session||session.date>today())return;
    const record={sessionId:session.id,date:session.date,status:d.get('status'),actualMinutes:Number(d.get('actualMinutes')),soreness:Number(d.get('soreness')),pain:d.get('pain')==='yes',notes:String(d.get('notes')).trim(),recordedAt:new Date().toISOString()};
    if((record.status==='skipped'&&record.actualMinutes!==0)||(record.status!=='skipped'&&record.actualMinutes<=0))return $('#strength-feedback-error').textContent='Skipped sessions need zero minutes; other outcomes need positive actual time.';
    if(commit(s=>{if(s.strengthRoom.records.some(r=>r.sessionId===record.sessionId))throw Error('This session already has feedback.');s.strengthRoom.records.push(record);s.strengthRoom.records=s.strengthRoom.records.slice(-500);if(record.soreness>=4)s.profile.recovery='poor';if(record.pain){s.profile.limitation='restricted';s.profile.strength.restrictions='restricted';}})){$('#modal').close();notify('Strength outcome saved. Review the cycling proposal if recovery or restrictions changed.');}return;
  }
  if(f.id==='profile-form') {
    const p={...state.profile,availabilityAssumed:false,weeklyTargetMinutes:d.get('weeklyTargetMinutes')!==''?Number(d.get('weeklyTargetMinutes')):null,recoveryWeekEnd:d.get('recoveryWeekEnd')||'',name:String(d.get('name')).trim(),goal:d.get('goal'),experience:d.get('experience'),weeklyMinutes:Number(d.get('weeklyMinutes')),longestMinutes:Number(d.get('longestMinutes')),availability:DAYS.map((_,i)=>Number(d.get(`day${i}`))),timezone:String(d.get('timezone')).trim(),units:d.get('units'),preference:d.get('preference'),equipment:d.getAll('equipment'),otherExerciseDays:d.getAll('otherDays').map(Number),eventDate:d.get('eventDate'),eventDistanceKm:d.get('eventDistanceKm')?Number(d.get('eventDistanceKm')):null,eventDurationMinutes:d.get('eventDurationMinutes')?Number(d.get('eventDurationMinutes')):null,eventTerrain:d.get('eventTerrain'),recovery:d.get('recovery'),limitation:d.get('limitation'),bodyMassKg:d.get('bodyMassKg')?Number(d.get('bodyMassKg')):null,maxHeartRate:d.get('maxHeartRate')?Number(d.get('maxHeartRate')):null,coach:{confirmed:d.has('coachConfirmed'),focus:d.get('coachFocus'),goalDetail:String(d.get('goalDetail')||'').trim(),cycleStart:d.get('cycleStart'),checkInDate:d.get('checkInDate'),fatigue:Number(d.get('fatigue')),sleep:Number(d.get('sleep')),soreness:Number(d.get('soreness')),motivation:Number(d.get('motivation')),intervalExperience:d.get('intervalExperience'),strengthDays:d.getAll('strengthDays').map(Number)},threshold:d.get('ftp')?{watts:Number(d.get('ftp')),method:d.get('ftpMethod'),date:d.get('ftpDate'),version:crypto.randomUUID()}:null};
    if(!commit(s=>{s.profile=structuredClone(p);}))return;
    preview(p,state.onboarded?'Goals or availability updated':'Initial plan proposed');
  }
  if(f.id==='ride-form') {
    try {
      const a={id:crypto.randomUUID(),title:String(d.get('title')).trim(),date:d.get('date'),minutes:Number(d.get('minutes')),distanceKm:d.get('distance')?Number(d.get('distance'))*(state.profile.units==='imperial'?1.609344:1):null,rpe:d.get('rpe')?Number(d.get('rpe')):null,discipline:d.get('discipline'),source:'manual',recordedAt:new Date().toISOString()};validateActivity(a);if(a.date>today())throw Error('Activities cannot be dated in the future.');
      if(state.activities.some(r=>r.date===a.date&&r.minutes===a.minutes&&r.title===a.title))throw Error('That activity is already recorded.');
      if(commit(s=>s.activities.push(a))){$('#modal').close();notify('Activity saved. Review a new weekly proposal to use it.');}
    }catch(err){$('#ride-error').textContent=err.message;}
  }
  if(f.id==='feedback-form') {
    try {
      const id=f.dataset.id,status=d.get('status'),actualMinutes=Number(d.get('actualMinutes')),feeling=d.get('feeling'),activityId=d.get('activityId');
      if(status==='skipped'&&actualMinutes!==0)throw Error('A skipped workout must have zero actual minutes.');
      if(status!=='skipped'&&actualMinutes<=0)throw Error('Enter actual minutes, or mark the workout skipped.');
      const match=state.activities.find(a=>a.id===activityId);if(activityId&&(!match||match.minutes!==actualMinutes||status==='skipped'))throw Error('Matched activity time must equal actual minutes; skipped sessions cannot have a match.');
      if(commit(s=>{const w=s.plan.workouts.find(w=>w.id===id);if(w.status!=='planned')throw Error('This outcome is already recorded.');w.status=status;w.feedback={actualMinutes,feeling,recordedAt:new Date().toISOString()};if(status!=='skipped'){w.activityId=activityId||crypto.randomUUID();if(!activityId)s.activities.push({id:w.activityId,date:w.date,title:w.title,minutes:actualMinutes,distanceKm:null,rpe:null,discipline:'cycling',source:s.mode==='synthetic'?'synthetic':'manual',recordedAt:new Date().toISOString()});}if(feeling==='poor')s.profile.recovery='poor';})){$('#modal').close();preview(state.profile,`Workout ${status}${feeling==='poor'?' · poor recovery':''}`);}
    }catch(err){$('#feedback-error').textContent=err.message;}
  }
});
