async function stravaRequest(route) {
  const response=await fetch(`/api/strava/${route}`,{method:'POST',headers:{'X-CSRF-Token':stravaStatus.csrf},credentials:'same-origin'});
  const result=await response.json();if(!response.ok)throw Error(result.error||'Strava request could not be completed.');return result;
}
async function refreshStrava() {
  const previous=JSON.stringify([stravaStatus,stravaActivities]);
  try {
    const response=await fetch('/api/strava/status',{credentials:'same-origin'});
    if(!response.ok)throw Error('Connection service unavailable. Restart the updated server and reload this page.');
    stravaStatus={...await response.json(),loading:false};
    if(stravaStatus.connected){const r=await fetch('/api/strava/activities',{credentials:'same-origin'});if(!r.ok)throw Error('Could not refresh activity records.');const data=await r.json();const range=calendarWindow(today());stravaActivities=data.activities.filter(a=>{const day=dateInZone(a.startDate,state.profile.timezone);return day>=range.start&&day<=range.end;});stravaStatus={...data,activities:undefined,loading:false};}
    else stravaActivities=[];
  }catch(error){stravaStatus={...stravaStatus,loading:false,error:error.message};}
  applyStravaRecords();
  if(['connection','history','week'].includes(view)&&!$('#modal').open&&previous!==JSON.stringify([stravaStatus,stravaActivities])){const scroll=window.scrollY;render();window.scrollTo(0,scroll);}
}
function applyStravaRecords() {
  if(!stravaStatus.connected){if(state.mode==='strava'){state=localState;pending=null;if($('#modal').open)$('#modal').close();}stravaWorkspace=null;return;}
  if(!useStravaCoaching)return;
  const profile=stravaWorkspace?.profile||localState.profile;
  const mapped=fromStrava(stravaActivities,profile.timezone,localDate(profile.timezone));rejectedStrava=mapped.rejected;
  if(!stravaWorkspace)stravaWorkspace=createStravaWorkspace(localState,mapped.activities);
  else {const next=[...mapped.activities,...stravaWorkspace.activities.filter(a=>a.source==='manual')];if(JSON.stringify(next)!==JSON.stringify(stravaWorkspace.activities)){stravaWorkspace.activities=next;stravaWorkspace.revision++;}}
  state=stravaWorkspace;
}
render();
void refreshStrava();
setInterval(()=>{if(!stravaBusy&&!document.hidden)void refreshStrava();},10000);
